mapper.update:
update agent_tool_approval a
set a.decision_status = #{decisionStatus},
a.execution_status = #{executionStatus},
a.reviewer_user_id = #{reviewerUserId},
a.decision_comment = #{decisionComment},
a.decided_at = #{now},
a.updated_at = #{now},
a.version = a.version + 1
where a.approval_id = #{approvalId}
and a.tenant_id = #{tenantId}
and a.decision_status = 'PENDING'
and a.expires_at > #{now}
and a.version = #{expectedVersion}

update agent_tool_approval a
set a.decision_status = 'EXPIRED',
a.execution_status = 'CANCELLED',
a.decided_at = #{now},
a.updated_at = #{now},
a.version = a.version + 1
where a.approval_id = #{approvalId}
and a.decision_status = 'PENDING'
and a.expires_at <= #{now}
and a.version = #{expectedVersion}
